import { epochOf, nowEpoch } from "@dcortex/canvas-format";
import { useEffect, useState, type FormEvent } from "react";
import type { ApiClient } from "./api/client.js";

/** Pre-expiry re-auth — ADR 35 §3: the warning leads to an IN-PLACE modal (never a
 * navigation), so a controller's half-typed verdict reason survives the 12-hour-shift
 * session boundary. expiresAt comes from the session probe. */

export function SessionExpiryGuard({
  client,
  warnBeforeMs = 10 * 60 * 1000,
}: {
  client: ApiClient;
  warnBeforeMs?: number;
}) {
  const [warning, setWarning] = useState(false);
  const [modal, setModal] = useState(false);
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | undefined>();

  useEffect(() => {
    let timer: ReturnType<typeof setTimeout> | undefined;
    void client
      .get<{ expiresAt: string }>("/api/auth/session")
      .then(({ expiresAt }) => {
        const warnIn = epochOf(expiresAt) - nowEpoch() - warnBeforeMs;
        timer = setTimeout(() => setWarning(true), Math.max(warnIn, 0));
      })
      .catch(() => {}); // unauthenticated boot — the api client routes to login
    return () => {
      if (timer) clearTimeout(timer);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function reauth(e: FormEvent) {
    e.preventDefault();
    setError(undefined);
    try {
      await client.post("/api/auth/login", { username, password });
      setModal(false);
      setWarning(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : "login failed");
    }
  }

  if (!warning) return null;
  return (
    <>
      <div className="banner">
        Session expires soon —{" "}
        <button className="btn" style={{ padding: "2px 10px" }} onClick={() => setModal(true)}>
          Sign in again
        </button>
      </div>
      {modal && (
        <div
          role="dialog"
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,.5)",
            display: "grid",
            placeItems: "center",
            zIndex: 10,
          }}
        >
          <form onSubmit={reauth} className="rcard" style={{ width: 320, cursor: "default", display: "grid", gap: 10 }}>
            <strong>Re-authenticate</strong>
            <input aria-label="username" placeholder="Username" value={username} onChange={(e) => setUsername(e.target.value)} />
            <input aria-label="password" type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} />
            {error && <div className="pill err">{error}</div>}
            <button className="btn primary" type="submit">
              Sign in
            </button>
          </form>
        </div>
      )}
    </>
  );
}

